public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Define an adjacency matrix to represent the maze
    boolean[][] adjMatrix = new boolean[n][n];
    for (int[] path : paths) {
        int startIndex = path[0];
        int endIndex = path[1];
        adjMatrix[startIndex][endIndex] = true;
    }

    // Perform BFS on the maze
    Queue<Integer> queue = new LinkedList<>();
    boolean[] visited = new boolean[n];
    queue.add(start[0]);
    visited[start[0]] = true;
    while (!queue.isEmpty()) {
        int currentIndex = queue.remove();
        if (currentIndex == end[0]) {
            return "can be travelled";
        }
        for (int i = 0; i < n; i++) {
            if (adjMatrix[currentIndex][i] && !visited[i]) {
                queue.add(i);
                visited[i] = true;
            }
        }
    }
    return "cannot be travelled";
}
