            if (distance[next] == -1 || distance[next] > distance[current] + cost[next]) {
                distance[next] = distance[current] + cost[next];
                parent[next] = current;
            }
        }
        current = -1;
        for (int i = 0; i < n; i++) {
            if (distance[i] > distance[current]) {
                current = i;
            }
        }
    }

    // Compute and return minimum time
    int time = 0;
    for (int node = 0; node != n; node++) {
        if (hasApple[node]) {
            time += distance[node];
        }
    }
    return time;
}
