public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph with the given number of nodes
    // and the given edges
    Graph graph = new Graph(n, edges);

    // Initialize a queue to breadth-first search the graph
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);

    // Initialize a set to keep track of nodes visited
    Set<Integer> visited = new HashSet<>();
    visited.add(0);

    // Initialize a list to store the minimum time to collect all apples
    List<Integer> minTime = new ArrayList<>();
    minTime.add(0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Extract the node from the head of the queue
        int node = queue.poll();

        // If the node has an apple, add its minimum time to the list
        if (hasApple[node]) {
            minTime.add(minTime.get(node) + 1);
        }

        // Loop through the neighbors of the node
        for (int neighbor : graph.neighbors[node]) {
            // If the neighbor has not been visited, mark it as visited and add it to the queue
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    // Return the minimum time to collect all apples
    return minTime.stream().reduce(Integer::min).orElse(0);
}

