public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a distance array with initial distance as 0
    int[] dist = new int[n];
    Arrays.fill(dist, 0);

    // Create a min heap to keep track of the nodes to visit
    PriorityQueue<Node> minHeap = new PriorityQueue<>();

    // Add node 0 with distance 0
    minHeap.add(new Node(0, 0));

    // Loop until the min heap is empty
    while (!minHeap.isEmpty()) {
        // Remove the node with minimum distance from the min heap
        Node currNode = minHeap.poll();

        // If the current node has an apple and its distance is less than the current maximum distance
        if (hasApple[currNode.val] && currNode.dist < dist[currNode.val]) {
            // Update the maximum distance with the current distance and break the loop
            dist[currNode.val] = currNode.dist;
            break;
        }

        // Add the children of the current node to the min heap with their distances calculated
        int child1 = currNode.val * 2 + 1;
        int child2 = currNode.val * 2 + 2;
        if (child1 < n) {
            minHeap.add(new Node(child1, currNode.dist + 1));
        }
        if (child2 < n) {
            minHeap.add(new Node(child2, currNode.dist + 1));
        }
    }

    // Return the maximum distance if the destination node has an apple
    // Otherwise, return 0
    return dist[n - 1] == Integer.MAX_VALUE ? 0 : dist[n - 1];
}

private static class Node implements Comparable<Node> {
    // Node value and distance
    int val, dist;

    public Node(int val, int dist) {
        this.val = val;
        this.dist = dist;
    }

    @Override
    public int compareTo(Node node) {
        // Compare the distances
        return dist - node.dist;
    }
}
