public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Step 1: Initialize a graph with n nodes and the given edges
    Graph graph = new Graph(n, edges);

    // Step 2: Perform a depth-first search (DFS) of the graph
    DFS dfs = new DFS(graph);
    dfs.startFrom(0);

    // Step 3: Keep track of the time spent at each node while visiting it
    int[] timeSpent = new int[n];
    for (int i = 0; i < n; i++) {
        timeSpent[i] = -1;
    }

    // Step 4: Iterate over the nodes in the DFS order and update the time spent at each node
    for (int i = 0; i < n; i++) {
        int currentNode = dfs.getOrderedNodes().get(i);
        int currentTime = dfs.getOrderedTimes().get(i);
        timeSpent[currentNode] = currentTime;

        // If the current node has an apple or is the target node, update the minimum time
        if (hasApple[currentNode]) {
            minTime = currentTime;
        }
    }

    // Step 5: Return the minimum time
    return minTime;
}

class Graph {
    int n;
    List<List<Integer>> edges;

    public Graph(int n, int[][] edges) {
        this.n = n;
        this.edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> neighbors = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                neighbors.add(0);
            }
            this.edges.add(neighbors);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < edges.length; j++) {
                int neighbor = edges[j][0];
                int weight = edges[j][1];
                edges[i].set(neighbor, weight);
            }
        }
    }
}

class DFS {
    Graph graph;
    int n;
    int time = 0;
    boolean[] visited;
    boolean[] finished;
    List<Integer> orderedNodes;
    List<Integer> orderedTimes;

    public DFS(Graph graph) {
        this.graph = graph;
        this.n = graph.n;
        this.visited = new boolean[n];
        this.finished = new boolean[n];
        this.orderedNodes = new ArrayList<>();
        this.orderedTimes = new ArrayList<>();
    }

    public void startFrom(int node) {
        this.visited[node] = true;
        this.finished[node] = true;
        time++;
        traverse(node);
    }

    public void traverse(int node) {
        for (int i = 0; i < n; i++) {
            int neighbor = graph.edges.get(node).get(i);
            if (neighbor > 0 && !visited[neighbor]) {
                visit(node, neighbor);
            }
        }
    }

    public void visit(int current, int neighbor) {
        visited[neighbor] = true;
        time++;
        // Queue up the neighbor and run DFS recursively
        if (!finished[neighbor]) {
            traverse(neighbor);
        }
        finished[neighbor] = true;
    }

    public List<Integer> getOrderedNodes() {
        return orderedNodes;
    }

    public List<Integer> getOrderedTimes() {
        return orderedTimes;
    }
}
