        char smallest = s.charAt(0);
        result += smallest;
        s = s.substring(1);

        // Step 2
        int smallestIndex = s.indexOf(smallest);
        while (smallestIndex >= 0) {
            s = s.substring(0, smallestIndex) + s.substring(smallestIndex + 1);
            smallestIndex = s.indexOf(smallest);
        }

        // Step 3
        char largest = s.charAt(s.length() - 1);
        result += largest;
        s = s.substring(0, s.length() - 1);

        // Step 4
        int largestIndex = s.lastIndexOf(largest);
        while (largestIndex >= 0) {
            s = s.substring(0, largestIndex) + s.substring(largestIndex + 1);
            largestIndex = s.lastIndexOf(largest);
        }
    }
    return result;
}
