public static boolean splitArraySameAverage(int[] nums) {
    double average = Arrays.stream(nums).sum() / nums.length;
    int[] left = new int[nums.length / 2];
    int[] right = new int[nums.length - left.length];

    for (int i = 0; i < nums.length; i++) {
        if (i < left.length) {
            left[i] = nums[i];
        } else {
            right[i - left.length] = nums[i];
        }
    }

    double leftSum = Arrays.stream(left).sum();
    double rightSum = Arrays.stream(right).sum();

    return Math.abs(leftSum - average) < 1e-9 && Math.abs(rightSum - average) < 1e-9;
}
