			currentCost = cost[i];
			minCost = Math.min(minCost, currentCost);
		} else if (i == 1) {
			previousCost = currentCost;
			currentCost = cost[i];
			minCost = Math.min(minCost, currentCost + previousCost);
		} else {
			previousCost = currentCost;
			currentCost = cost[i];
			minCost = Math.min(minCost, currentCost + previousCost);
