    while (arr.length != 1) {
        int x = threadLocal.get().nextInt(0, n - 1);
        int y = threadLocal.get().nextInt(0, n - 1);
        int delta = arr[x] - arr[y];
        minOps += Math.abs(delta);
        arr[x] -= delta;
        arr[y] += delta;
        n -= 1;
    }
    return minOps;
