public int kthFactor(int n, int k) {
    // Initialize a set to store factors
    Set<Integer> factors = new HashSet<>();

    // Add 1 and n to the set of factors
    factors.add(1);
    factors.add(n);

    // Loop through the factors and find the k-th
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }

