public static int maxUniqueSplit(String s) {
    if (s == null || s.length() < 1) {
        return 0;
    }

    // We use a hash map to keep track of the unique substrings
    Map<String, Integer> seenStrings = new HashMap<>();

    // We use a list to keep track of the substrings from back to front
    List<String> substrings = new ArrayList<>();

    // We iterate from the last character of the string
    for (int i = s.length() - 1; i >= 0; i--) {
        // We create a substring from the current character to the end of the string
        String substring = s.substring(i);

        // If the substring is not in the hash map, we add it and add it to the list
        if (!seenStrings.containsKey(substring)) {
            seenStrings.put(substring, 1);
            substrings.add(substring);
        }

        // We iterate from the current character to the end of the string
        for (int j = i + 1; j < s.length(); j++) {
            // We create a substring from the current character to the end of the string
            String substringB = s.substring(i, j);

            // If the substring is not in the hash map, we add it and add it to the list
            if (!seenStrings.containsKey(substringB)) {
                seenStrings.put(substringB, 1);
                substrings.add(substringB);
            }
        }
    }

    return substrings.size();
