public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] count = new int[1 << n];
    Arrays.fill(count, 1);
    for (int i = 0; i < n; i++) {
        int mask = (1 << i) - 1;
        for (int j = 0; j < n; j++) {
            if ((mask & (1 << j)) == 0 && s.charAt(i) == s.charAt(j)) {
                count[mask | (1 << j)] = Math.max(count[mask | (1 << j)], count[mask] + 1);
            }
        }
    }
    return Arrays.stream(count).max().getAsInt();
}
