class MinOperationsByLevel {
    public static int minOperationsByLevel(String[] logs) {
        int operations = 0;
        List<String> folders = new ArrayList<>();

        for (String log : logs) {
            if (log.equals("../")) {
                if (!folders.isEmpty()) {
                    folders.remove(folders.size() - 1);
                }
            } else {
                folders.add(log);
            }
        }

        int levels = folders.size();
        if (levels == 0) {
            return 0;
        }

        int[] minOperationsByLevel = new int[levels];
        for (int i = 0; i < levels; i++) {
            minOperationsByLevel[i] = Math.max(0, levels - i - 1);
        }

        for (String folder : folders) {
            if (folder.equals("../")) {
                continue;
            }
            int level = folder.equals(".") ? levels - 1 : folder.lastIndexOf("/");
            minOperationsByLevel[level] = Math.min(minOperationsByLevel[level], Math.max(0, levels - level - 1));
        }

        for (int operation : minOperationsByLevel) {
            operations += operation;
        }

        return operations;
    }
}
