public static int longestLine(int[][] mat) {
    int longest = 0;
    for (int i = 0; i < mat.length; i++) {
        for (int j = 0; j < mat[0].length; j++) {
            int temp;
            if (mat[i][j] == 1) {
                if (i == 0 || j == 0) {
                    temp = 1;
                } else {
                    temp = Math.max(longestLine(mat, i - 1, j - 1) + 1, longestLine(mat, i - 1, j) + 1, longestLine(mat, i, j - 1) + 1);
                }
                if (temp > longest) {
                    longest = temp;
                }
            }
        }
    }
    return longest;
}

