public static String addThousandSeparator(int n) {
    // If the input is zero, return the string representation of zero.
    if (n == 0) {
        return "0";
    }

    // Create a StringBuilder to store the result.
    StringBuilder sb = new StringBuilder();

    // Add the minus sign if the input is negative.
    if (n < 0) {
        sb.append('-');
        n = -n;
    }

    // Iterate through the digits of the input in reverse order.
    String[] digits = Integer.toString(n).split("");
    for (int i = digits.length - 1; i >= 0; i--) {
        // If the digit and the next digit form a "thousand" (i.e., 3 digits), add a dot.
        if (i > 0 && i % 3 == 0) {
            sb.append('.');
        }
        sb.append(digits[i]);
    }

    // Return the resulting string.
    return sb.toString();
}
