import java.util.Set;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        HashSet<int[]> set = new HashSet<>();
        for (int i = 0; i < A.length; i++) {
            int[] permutation = new int[A.length];
            for (int j = 0; j < A.length; j++) {
                permutation[j] = i == j ? A[i] : A[j];
            }
            if (set.contains(permutation)) {
                continue;
            }
            int sum = 0;
            for (int j = 0; j < permutation.length - 1; j++) {
                sum += permutation[j] * permutation[j + 1];
            }
            if (Math.sqrt(sum) == (int) Math.sqrt(sum)) {
                set.add(permutation);
            }
        }
        return set.size();
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8}));
        System.out.println(squarePermutations(new int[]{2, 2, 2}));
    }
}
