public static int squarePermutations(int[] A) {
  // Complete the function body
  int[][] permutations = new int[A.length][A.length]; // to store all possible permutations of A
  for (int i = 0; i < A.length; i++) {
    permutations[i] = Arrays.copyOf(A, A.length); // copies A to each row of permutations
    for (int j = i + 1; j < A.length; j++) {
      if (Math.abs(A[i] - A[j]) == 1) { // if there is only one difference between two adjacent elements
        swap(permutations[i], i, j); // swap them
      }
    }
  }

  int numSquarePermutations = 0;
  for (int[] permutation : permutations) {
    boolean isSquareArray = true; // checks if the permutation is a square array
    for (int i = 1; i < permutation.length; i++) {
      if (Math.sqrt(permutation[i - 1] + permutation[i]) != (int) Math.sqrt(permutation[i - 1] + permutation[i])) {
        isSquareArray = false;
        break;
      }
    }
    if (isSquareArray) {
      numSquarePermutations++;
    }
  }
  return numSquarePermutations;
}

private static void swap(int[] arr, int i, int j) {
  int tmp = arr[i];
  arr[i] = arr[j];
  arr[j] = tmp;
