public static int findNthUglyNumber(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be a non-negative integer");
    }

    // Base case: If n is 1, return 1
    if (n == 1) {
        return 1;
    }

    // Create an array to store the calculated ugly numbers
    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;

    int nextUglyNumberIndex = 1;
    int nextUglyNumber = 1;

    while (nextUglyNumberIndex < n) {
        // Calculate the next ugly number
        nextUglyNumber = getNextUglyNumber(uglyNumbers, nextUglyNumberIndex);

        // Store the next ugly number in the array
        uglyNumbers[nextUglyNumberIndex] = nextUglyNumber;
        nextUglyNumberIndex++;
    }

    // Return the nth ugly number
    return uglyNumbers[n - 1];
}

/**
 * Returns the next ugly number in the sequence.
 *
 * @param uglyNumbers        An array of calculated ugly numbers.
 * @param nextUglyNumberIndex The index of the next ugly number to be calculated.
 * @return The next ugly number.
 */
private static int getNextUglyNumber(int[] uglyNumbers, int nextUglyNumberIndex) {
    int nextUglyNumber = 0;

    // Calculate the next ugly number by taking the minimum of the next ugly number
    // in each sequence
    nextUglyNumber = Math.min(uglyNumbers[nextUglyNumberIndex - 1],
        Math.min(uglyNumbers[nextUglyNumberIndex - 1] * 2,
            Math.min(uglyNumbers[nextUglyNumberIndex - 1] * 3,
                uglyNumbers[nextUglyNumberIndex - 1] * 5)));

    return nextUglyNumber;
}
