/**
 * Reverses the characters of each word in the given string while maintaining the original word order.
 *
 * @param s The input string containing words separated by spaces.
 * @return The string with characters of each word reversed.
 */
public static String reverseWords(String s) {
    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Create a new array to store the reversed words
    String[] reversedWords = new String[words.length];

    // Iterate over the words and reverse each one
    for (int i = 0; i < words.length; i++) {
        // Reverse the current word
        String word = words[i];
        String reversedWord = "";
        for (int j = word.length() - 1; j >= 0; j--) {
            reversedWord += word.charAt(j);
        }

        // Store the reversed word in the reversedWords array
        reversedWords[i] = reversedWord;
    }

    // Join the reversed words with spaces and return the result
    return String.join(" ", reversedWords);
}

